import React, { useState } from 'react';
import { Button } from '../../../components/common/Button';

export function ExportControls({
  onExport,
  isExporting,
  datasetId,
  targetId,
  groupSplitCol = 'run_id',
}) {
  const [copiedCode, setCopiedCode] = useState(false);
  const [showCode, setShowCode] = useState(false);

  const starterPythonCode = `# ==============================================================================
# NASA FLAME — Predictive-Modeling Starter Script
# Generated by NASA FLAME Scientific Intelligence Dashboard
# Enforces Group-Aware Cross-Validation to eliminate data leakage
# ==============================================================================

import pandas as pd
import numpy as np
from sklearn.model_selection import GroupKFold, cross_val_score
from sklearn.ensemble import HistGradientBoostingRegressor
from sklearn.metrics import mean_squared_error, r2_score

# 1. Load exported NASA FLAME dataset (guaranteed 1:1 match with preview)
df = pd.read_csv("${datasetId}_modeling_data.csv")
print(f"Loaded {len(df)} records from ${datasetId}")

# 2. Separate Features, Target, and Group Identifier
target_col = "${targetId || 'oxygen_consumption_delta_pct'}"
group_col = "${groupSplitCol}"

# Drop missing target rows if any (silent imputation is forbidden)
df = df.dropna(subset=[target_col]).copy()

# Features (drop non-predictive group identifier and target)
cols_to_drop = [c for c in [target_col, group_col] if c in df.columns]
X = df.drop(columns=cols_to_drop)
y = df[target_col]
groups = df[group_col] if group_col in df.columns else np.arange(len(df))

# Convert categorical columns (e.g. fuel_material) for GBDT
for col in X.select_dtypes(include=['object']).columns:
    X[col] = X[col].astype('category')

print(f"Feature matrix shape: {X.shape}, Target: {target_col}")

# 3. Group-Aware Cross-Validation (Prevents intra-run autocorrelation leakage)
gkf = GroupKFold(n_splits=min(5, len(np.unique(groups))))
model = HistGradientBoostingRegressor(random_state=42)

cv_scores = cross_val_score(
    model, X, y, groups=groups, cv=gkf, scoring="r2"
)

print(f"GroupKFold R² across folds: {np.round(cv_scores, 3)}")
print(f"Mean Generalization R²: {cv_scores.mean():.3f} (± {cv_scores.std():.3f})")
`;

  const handleCopyCode = () => {
    navigator.clipboard.writeText(starterPythonCode);
    setCopiedCode(true);
    setTimeout(() => setCopiedCode(false), 2800);
  };

  return (
    <div className="bg-white border border-slate-200 rounded-2xl p-4 sm:p-5 shadow-sm space-y-4">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div>
          <span className="text-[11px] font-mono uppercase tracking-wider text-orange-600">
            Export Center
          </span>
          <h3 className="text-sm font-semibold text-slate-900">
            Download Scientifically Grounded Datasets
          </h3>
          <p className="text-xs text-slate-500 mt-0.5">
            Zero fabricated data. Preserves physical units, experimental run IDs, and extraction provenance.
          </p>
        </div>

        {/* Action Buttons */}
        <div className="flex items-center gap-2 flex-wrap">
          <Button
            variant="accent"
            size="md"
            onClick={() => onExport('csv')}
            disabled={isExporting}
            className="bg-orange-500 hover:bg-orange-600 text-white font-semibold text-xs shadow-sm"
          >
            📥 Export CSV (.csv)
          </Button>

          <Button
            variant="secondary"
            size="md"
            onClick={() => onExport('json')}
            disabled={isExporting}
            className="text-xs font-medium border-slate-200 bg-slate-50 hover:bg-slate-100 text-slate-700"
          >
            📄 Metadata JSON (.json)
          </Button>

          <Button
            variant="secondary"
            size="md"
            onClick={() => onExport('report')}
            disabled={isExporting}
            className="text-xs font-medium border-slate-200 bg-slate-50 hover:bg-slate-100 text-slate-700"
          >
            📊 Quality Report (.md)
          </Button>

          <Button
            variant="outline"
            size="md"
            onClick={() => setShowCode(!showCode)}
            className="text-xs font-mono border-slate-200 hover:border-slate-300 text-slate-700 bg-white hover:bg-slate-50"
          >
            {showCode ? 'Hide Python Code' : '💻 Python Starter Code'}
          </Button>
        </div>
      </div>

      {/* Collapsible Python Starter Code Drawer */}
      {showCode && (
        <div className="pt-3 border-t border-slate-200 space-y-2 animate-in fade-in duration-200">
          <div className="flex items-center justify-between">
            <span className="text-xs font-mono text-slate-700 flex items-center gap-2">
              <span>Python Starter Pipeline (Scikit-Learn GroupKFold)</span>
            </span>

            <button
              type="button"
              onClick={handleCopyCode}
              className="text-xs px-2.5 py-1 rounded-md bg-orange-50 hover:bg-orange-100 border border-orange-200 text-orange-700 font-mono transition-colors cursor-pointer"
            >
              {copiedCode ? '✓ Copied to Clipboard!' : 'Copy Python Code'}
            </button>
          </div>

          <pre className="p-3.5 rounded-xl bg-slate-900 border border-slate-800 text-[11px] font-mono text-slate-200 overflow-x-auto max-h-[300px] leading-relaxed">
            {starterPythonCode}
          </pre>
        </div>
      )}
    </div>
  );
}
